import * as React from "react"
import { PageProps, graphql } from "gatsby"
import  data  from "../data/data.json";
import { UserProfile } from "../interfaces";
import Layout from "../components/layout"
import images from "../images";
import { useTranslation } from "gatsby-plugin-react-i18next";
import ContactForm from "../components/contactForm";
import { SlScreenSmartphone } from "react-icons/sl";
import { HiOutlinePhone } from "react-icons/hi2";

const userData: UserProfile = data;

const ContactPage: React.FC<PageProps> = () => {
  const { t } = useTranslation();
      function formatPhoneNumber(phoneNumber: string) {
    const cleanedPhoneNumber = phoneNumber.replace(/\D+/g, "");
    if (cleanedPhoneNumber.startsWith("1")) {
      return `${cleanedPhoneNumber.slice(1, 4)} ${cleanedPhoneNumber.slice(
        4,
        7
      )} ${cleanedPhoneNumber.slice(7, 12)}`;
    } else {
      return cleanedPhoneNumber;
    }
  }
  return (
    <Layout 
      data={userData}
      iconAndTextColor="DeepSea"
      footerLogoFill="fill-Tofu"
      bgColorPage="Trooper"
      bgImage={images.bgContact.src}
      footerBackground="linear-gradient(to top, rgba(32,47,47,1) 0%,rgba(32,47,47,0) 100%)"
    >
        <section className={styles.section}>
          <div className="flex flex-col">
            <h1 className="head-3 uppercase mb-4">{t("contact.title")}</h1>
            <p className="body-3 mb-2">{userData.address}</p>
            <p className="body-3 mb-2">{userData.city}, {userData.province}</p>
            <p className="body-3 mb-2">{userData.postalCode}</p>
            <p className="body-3 flex mb-2"><HiOutlinePhone /><a className="ml-2" href={`tel:${userData.phone}`}>{formatPhoneNumber(userData.phone)}</a></p>
            <p className="body-3 flex  mb-2"><SlScreenSmartphone /><a className="ml-2" href={`tel:${userData.cel}`}>{formatPhoneNumber(userData.cel)}</a></p>
          </div>
            <div className="mt-6 sm:mt-0 relative z-20">
                <ContactForm />
            </div>
        </section>
    </Layout>
  )
}

export default ContactPage

export const query = graphql`
  query ($language: String!) {
    locales: allLocale(filter: { language: { eq: $language } }) {
      edges {
        node {
          ns
          data
          language
        }
      }
    }
  }
`;

const styles = {
  section: "flex flex-col sm:flex-row justify-between mt-24 mb-32 sm:mb-0 mx-8 sm:mx-16",
}
import SEO from "../components/seo";
import type { HeadProps } from "gatsby";
import translations from "../locales/en/index.json";
export const Head = ({ location, pageContext }: HeadProps<Record<string, unknown>, { language?: string; i18n?: { originalPath?: string } }>) => (
  <SEO
    data={userData}
    title={translations.seo.contact.title}
    description={translations.seo.contact.description}
    language={pageContext.language ?? "en"}
    languages={["en"]}
    defaultLanguage="en"
    originalPath={pageContext.i18n?.originalPath ?? location.pathname}
    schemaType="ProfessionalService"
    pageSchemaType="ContactPage"
    pageSchemaName="Contact Reef Cleaning Company"
  />
);
